import{seeded as m}from"./city.min.js";import{sunTimes as g,dayOfYear as d}from"./daylight.min.js";const f=Math.PI/180,l=3600*1e3;export const LATITUDE=40,POLE=[Math.cos(LATITUDE*f),Math.sin(LATITUDE*f),0],SYNODIC_DAYS=29.530588853,NEW_MOON=Date.UTC(2e3,0,6,18,14);const I=861640905e-1;export function declination(o){return 23.44*f*Math.cos(2*Math.PI*(d(o)-172)/365)}export function direction(o,t,e=LATITUDE){const n=e*f,s=-Math.cos(t)*Math.sin(o),c=Math.cos(n)*Math.sin(t)-Math.sin(n)*Math.cos(t)*Math.cos(o),a=Math.sin(n)*Math.sin(t)+Math.cos(n)*Math.cos(t)*Math.cos(o);return[c,a,s]}function P(o){return o.getHours()+o.getMinutes()/60+o.getSeconds()/3600+o.getMilliseconds()/l}export function moonAge(o){return((o.getTime()-NEW_MOON)/(24*l)/SYNODIC_DAYS%1+1)%1}const y=(o,t)=>Math.acos(Math.min(1,Math.max(-1,o[0]*t[0]+o[1]*t[1]+o[2]*t[2])));export function skyAt(o){const{sunrise:t,sunset:e}=g(o),n=(t+e)/2,s=(e-t)/2,c=declination(o),a=LATITUDE*f,r=Math.acos(Math.min(1,Math.max(-1,-Math.tan(a)*Math.tan(c)))),h=P(o),i=direction((h-n)/s*r,c),u=moonAge(o),M=direction((h-n)/12*Math.PI-2*Math.PI*u,c*Math.cos(2*Math.PI*u)),p=(o.getTime()/I%1+1)%1*2*Math.PI;return{sun:i,moon:M,age:u,turn:p,sunHeight:Math.asin(i[1]),moonHeight:Math.asin(M[1]),elongation:y(i,M)}}export function lightFrom(o){const t=Math.sin(4*f);let e=[.3,1,.2];o.sunHeight>-6*f?e=o.sun:o.moonHeight>0&&(e=o.moon);let[n,s,c]=e;if(s<t){const r=Math.hypot(n,c)||1,h=Math.sqrt(1-t*t)/r;n*=h,c*=h,s=t}const a=Math.hypot(n,s,c);return[n/a,s/a,c/a]}export function discBasis(o,t){const e=(r,h)=>r[0]*h[0]+r[1]*h[1]+r[2]*h[2],n=r=>{const h=e(r,o),i=r.map((M,p)=>M-h*o[p]),u=Math.hypot(...i);return u>1e-6?i.map(M=>M/u):null},s=n(t)||n([0,1,0])||n([1,0,0]),c=o.map(r=>-r),a=[c[1]*s[2]-c[2]*s[1],c[2]*s[0]-c[0]*s[2],c[0]*s[1]-c[1]*s[0]];return{right:s,up:a,normal:c}}export function starField(o=420,t=20260926){const e=m(t),n=[];for(let s=0;s<o;s++){const c=e()*2-1,a=e()*Math.PI*2,r=Math.sqrt(1-c*c);n.push([r*Math.cos(a),c,r*Math.sin(a),.35+.65*e()**3])}return n}export function dayLapse(o,{seconds:t=30,stepped:e=!1}={}){let n=0;return{step(s){n=Math.min(t,n+Math.max(0,s));const c=n/t*24,a=e&&n<t?Math.floor(c):c;return{at:o+a*l,done:n>=t}}}}export const CLOUDS={altitude:4800,span:411e3,tile:24e3,size:1024,cells:22,seed:20260925};export function cloudPuffs(o=CLOUDS){const t=m(o.seed),e=[];for(let n=0;n<o.cells;n++){const s=t(),c=t(),a=.03+t()*.05,r=10+Math.floor(t()*16);for(let h=0;h<r;h++){const i=t()*Math.PI*2,u=Math.sqrt(t()),M=s+Math.cos(i)*u*a*1.8,p=c+Math.sin(i)*u*a,x=a*(.35+t()*.4)*(1-u*.4);e.push([(M%1+1)%1,(p%1+1)%1,x,.55+t()*.35])}}return e}export function wrappedPuffs(o){const t=[];for(const[e,n,s,c]of o)for(const a of[-1,0,1])for(const r of[-1,0,1]){const h=e+a,i=n+r;h+s<0||h-s>1||i+s<0||i-s>1||t.push([h,i,s,c])}return t}export function cloudCover(o,t=64){const e=wrappedPuffs(o);let n=0;for(let s=0;s<t;s++)for(let c=0;c<t;c++){const a=(c+.5)/t,r=(s+.5)/t;e.some(([h,i,u])=>Math.hypot(a-h,r-i)<u)&&n++}return n/(t*t)}
